// ==== Editor-shipped levels ====

// Regenerated in full every time a level is shipped from `/editor` (the
// "Ship to sand-levels.ts" button, via `npm run level-writer`) — this array
// always mirrors the editor's current level list exactly, so a level deleted
// in the editor disappears from here on the next ship rather than lingering.
// A draft imported from a level living outside this block updates that
// level's own const instead of appearing here at all — see this file's
// header comment.
// Hand edits inside this block are overwritten on the next ship; edit the
// level in the editor instead.
//
// "Meditation" (id 51) removed on request ("Xóa level meditation trong
// gallery") — it was the one editor-shipped level past the 50 hand-authored
// ones (BUILT_IN_LEVELS below spreads this array in right after
// `fiftiethLevel`), so this block goes back to empty rather than the id
// simply being skipped. If it still exists as a draft in the editor's own
// (browser-local) level list, the NEXT "Ship to sand-levels.ts" will bring it
// right back — delete it there too if it should stay gone for good.
export const EDITOR_LEVELS: SandLevelConfig[] = [];
// ==== End editor-shipped levels ====

